// ── Public Hand component ─────────────────────────────────────────────────────

export function Hand({
	className,
	side = "right",
	registeredFingers = [],
	selectedFinger = null,
	onFingerClick,
	interactive = false,
	readerStatus,
	captureActive = false,
	countdown = 0,
}: HandProps) {
	const sharedProps: InternalHandProps = {
		className,
		registeredFingers,
		selectedFinger,
		onFingerClick,
		interactive,
		readerStatus,
		captureActive,
		countdown,
	};

	if (side === "left") {
		return <LeftHand {...sharedProps} />;
	}

	return <RightHand {...sharedProps} />;
}
